package com.raptor.customfence_fabric.blocks;

import com.raptor.customfence_fabric.init.ModBlocksMetalFence;
import net.fabricmc.fabric.api.registry.OxidizableBlocksRegistry;

public class WaxableFence {

    public static void waxingFences() {

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_COPPER_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_COPPER_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_EXPOSED_COPPER_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_EXPOSED_COPPER_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_WEATHERED_COPPER_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_WEATHERED_COPPER_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_OXIDIZED_COPPER_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_OXIDIZED_COPPER_MANSION_FENCE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COPPER_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_COPPER_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.EXPOSED_COPPER_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_EXPOSED_COPPER_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.WEATHERED_COPPER_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_WEATHERED_COPPER_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.OXIDIZED_COPPER_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_OXIDIZED_COPPER_MANSION_FENCE_GATE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_IRON_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_IRON_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_EXPOSED_IRON_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_EXPOSED_IRON_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_WEATHERED_IRON_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_WEATHERED_IRON_MANSION_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_OXIDIZED_IRON_MANSION_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_OXIDIZED_IRON_MANSION_FENCE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.IRON_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_IRON_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.EXPOSED_IRON_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_EXPOSED_IRON_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.WEATHERED_IRON_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_WEATHERED_IRON_MANSION_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.OXIDIZED_IRON_MANSION_FENCE_GATE, ModBlocksMetalFence.WAXED_OXIDIZED_IRON_MANSION_FENCE_GATE);


        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_COPPER_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_COPPER_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_EXPOSED_COPPER_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_EXPOSED_COPPER_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_WEATHERED_COPPER_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_WEATHERED_COPPER_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_OXIDIZED_COPPER_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_OXIDIZED_COPPER_MESH_FENCE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COPPER_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_COPPER_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.EXPOSED_COPPER_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_EXPOSED_COPPER_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.WEATHERED_COPPER_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_WEATHERED_COPPER_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.OXIDIZED_COPPER_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_OXIDIZED_COPPER_MESH_FENCE_GATE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_IRON_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_IRON_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_EXPOSED_IRON_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_EXPOSED_IRON_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_WEATHERED_IRON_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_WEATHERED_IRON_MESH_FENCE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.COBBLESTONE_OXIDIZED_IRON_MESH_FENCE, ModBlocksMetalFence.COBBLESTONE_WAXED_OXIDIZED_IRON_MESH_FENCE);

        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.IRON_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_IRON_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.EXPOSED_IRON_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_EXPOSED_IRON_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.WEATHERED_IRON_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_WEATHERED_IRON_MESH_FENCE_GATE);
        OxidizableBlocksRegistry.registerWaxable(ModBlocksMetalFence.OXIDIZED_IRON_MESH_FENCE_GATE, ModBlocksMetalFence.WAXED_OXIDIZED_IRON_MESH_FENCE_GATE);

    }

}
